using System;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;
public static class ValidateRainRoadDrive {
 public static object Main(){
 if(!Application.isPlaying)throw new Exception("Requires Play Mode");var roads=UnityEngine.Object.FindObjectsByType<RainSoakedRoad>();var source=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();var original=source.GetComponent<Rigidbody>();bool kinematic=original.isKinematic,paused=EditorApplication.isPaused;var velocity=original.linearVelocity;var angular=original.angularVelocity;var mode=Physics.simulationMode;var weather=roads[0].weather;var field=typeof(ForestDayNightWeather).GetField("rain",BindingFlags.NonPublic|BindingFlags.Instance);float rain=(float)field.GetValue(weather);var blockages=UnityEngine.Object.FindAnyObjectByType<ForestRoadBlockages>();bool blocked=blockages.enabled;GameObject clone=null;
 try{EditorApplication.isPaused=true;Physics.simulationMode=SimulationMode.Script;original.isKinematic=true;blockages.enabled=false;
 object[] results=new object[2];float[] depths=new float[2];float[] slips=new float[2];
 for(int run=0;run<2;run++){
 field.SetValue(weather,run==0?0f:1f);foreach(var road in roads)road.Advance(1000);
 float z=-24;float sin=Mathf.Sin(z*Mathf.PI/50),x=12*sin*sin*sin;clone=UnityEngine.Object.Instantiate(source.gameObject,new Vector3(x+(run==0?-.8f:.8f),.7f,z),Quaternion.identity);var car=clone.GetComponent<VehiclePhysics>();car.automaticSimulation=false;car.externalControl=true;clone.GetComponent<VehiclePlayerInput>().enabled=false;var sound=clone.GetComponent<VehicleAudio>();if(sound!=null)sound.enabled=false;var body=clone.GetComponent<Rigidbody>();body.isKinematic=false;car.Initialize();car.SetNeutral(false);car.SetFourWheelDrive(true);car.SetTransmission(false,true);car.SetInput(new VehicleControlInput{brake=1});Physics.SyncTransforms();Action step=()=>{car.Simulate(.01f);Physics.Simulate(.01f);SoftGroundRuts.AdvanceAll(.01f);};for(int i=0;i<150;i++)step();var start=body.position;float peak=0;car.SetInput(new VehicleControlInput{throttle=.6f});for(int i=0;i<150;i++){step();peak=Mathf.Max(peak,car.SpeedKmh);slips[run]=Mathf.Max(slips[run],car.WheelspinSpeed);}var travel=Vector3.Distance(start,body.position);car.SetInput(new VehicleControlInput{brake=1});for(int i=0;i<150;i++)step();float before=roads.Where(r=>r.transform.position.z < -20 && r.transform.position.z > -40).Max(r=>r.GetComponent<SoftGroundRuts>().DugDepth);for(int i=0;i<400;i++)step();float after=roads.Where(r=>r.transform.position.z < -20 && r.transform.position.z > -40).Max(r=>r.GetComponent<SoftGroundRuts>().DugDepth);depths[run]=after;foreach(var road in roads)road.GetComponent<SoftGroundRuts>().Commit();results[run]=new{wet=run==1,travel,peakKmh=peak,peakSlip=slips[run],maximumRut=after,stoppedSettlement=after-before,grounded=car.Wheels.Count(w=>w.isGrounded)};UnityEngine.Object.DestroyImmediate(clone);clone=null;
 }
 if(depths[1]<depths[0]+.01f||depths[1]<.02f)throw new Exception("Wet ruts not stronger: dry="+depths[0]+" wet="+depths[1]);return new{success=true,runs=results};
 }finally{if(clone!=null)UnityEngine.Object.DestroyImmediate(clone);field.SetValue(weather,rain);original.isKinematic=kinematic;if(!kinematic){original.linearVelocity=velocity;original.angularVelocity=angular;}Physics.simulationMode=mode;EditorApplication.isPaused=paused;blockages.enabled=blocked;}
 }
}


